def md5(text):
    return hashlib.md5(text.encode("utf-8")).hexdigest()


def fail(message):
    print(message)
    print("NOTHING was written. Undo is not needed.")
    return 1


def main():
    planned = []
    notes = []
    for f in FILES:
        rel = f["path"]
        path = os.path.join(HERE, *rel.split("/"))
        if f["mode"] == "new_if_absent":
            if os.path.exists(path):
                print("ok  %-58s already here, kept as it is" % rel)
                continue
            planned.append((rel, path, f["content"]))
            print("ok  %-58s new file" % rel)
            continue
        if f["mode"] == "new":
            if os.path.exists(path):
                with open(path, "rb") as handle:
                    have = handle.read().decode("utf-8").replace("\r\n", "\n")
                if md5(have) == f["new_md5"]:
                    print("ok  %-58s already present, the same" % rel)
                    continue
                return fail("ERROR: %s already exists and differs from what "
                            "this patch adds." % rel)
            planned.append((rel, path, f["content"]))
            print("ok  %-58s new file" % rel)
            continue
        if not os.path.exists(path):
            return fail("ERROR: %s is not here. Save this patch in the "
                        "repository's root folder." % rel)
        with open(path, "rb") as handle:
            raw = handle.read()
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError:
            return fail("ERROR: %s is not UTF-8." % rel)
        if "\r\n" in text:
            text = text.replace("\r\n", "\n")
            notes.append("note: %s was CRLF in the working copy; written LF"
                         % rel)
        zone = None
        if f.get("clear"):
            mk = f["clear"]["marker"]
            if text.count(mk) != 1:
                return fail("ANCHOR FAIL: %s has no single run-record marker"
                            % rel)
            zone = text[text.index(mk):]
            text = text[:text.index(mk)]
        have = md5(text)
        if have == f["new_md5"]:
            return fail("ERROR: %s already carries this patch's change. "
                        "It has run before." % rel)
        exact = have == f["base_md5"]
        if f["mode"] == "whole" and not exact:
            return fail("ERROR: %s is not the version this patch was "
                        "built on (base moved). Compare it with the "
                        "repository in GitHub Desktop." % rel)
        for n, (old, new) in enumerate(f["edits"], 1):
            count = text.count(old)
            if count != 1:
                first = old.strip().splitlines()[0][:60] if old.strip() else ""
                return fail("ANCHOR FAIL: %s edit %d matched %d times: %r"
                            % (rel, n, count, first))
            text = text.replace(old, new)
        if exact and md5(text) != f["new_md5"]:
            return fail("ERROR: %s edited, but the result is not what this "
                        "patch was built to write." % rel)
        if not exact:
            notes.append("note: %s differed from the base outside the edited "
                         "lines; those lines were kept" % rel)
        if zone is not None:
            if zone.rstrip() in [a.rstrip() for a in f["clear"]["accept"]]:
                text = text + f["clear"]["stub"]
                notes.append("note: %s run-record zone emptied; it held what "
                             "your saved copy holds" % rel)
            else:
                text = text + zone
                notes.append("note: %s run-record zone KEPT as it is: it holds "
                             "something your saved copy does not" % rel)
        planned.append((rel, path, text))
        print("ok  %-58s %d edit(s)" % (rel, len(f["edits"])))

    for rel, path, text in planned:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8", newline="") as handle:
            handle.write(text)
    for note in notes:
        print(note)
    print("patch applied (%d file(s) written)" % len(planned))
    print("")
    print('NEXT:')
    print('  1. Run orrery_maintenance_run.py. Dashboard parity should match')
    print('     84 steps by name, with Typed Facts among them; the Ledger index')
    print('     moves L-421, L-262 and L-453 into the closed section; Skill')
    print('     manifest unchanged (this patch carries it). Expect every gating')
    print('     checker to pass and the gate path at 0.')
    print('  2. Move this script into documentation/; commit; push.')
    print('  3. Reinstall interactive-exhibit 1.16 (Settings > Skills), and copy')
    print('     PROJECT_INSTRUCTIONS.md into the Project instructions.')
    return 0


if __name__ == "__main__":
    sys.exit(main())
